def protocol_handlers(protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Step 1: Check if an explicit protocol version is provided.
    if protocol_version is not None:
        # If a tuple is not passed as the protocol version, raise an error.
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"Protocol version must be passed in a tuple, {type(protocol_version)} got instead."
            )
        # If the protocol version is not supported, return an empty dictionary.
        if protocol_version not in cls.SUPPORTED_PROTOCOLS:
            return {}
        # Otherwise, return a dictionary with the protocol version as the key and the handler class as the value.
        return {protocol_version: cls.SUPPORTED_PROTOCOLS[protocol_version]}
    # Step 2: If no explicit protocol version is provided, return all available versions.
    return {version: cls.SUPPORTED_PROTOCOLS[version] for version in cls.SUPPORTED_PROTOCOLS}

