def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(user_function):
        cache = {}
        use_count = {}
        kwd_mark = object()

        def wrapper(*args, **kwargs):
            if kwargs:
                key = args + (kwd_mark,) + tuple(sorted(kwargs.items()))
            else:
                key = args
            if key in cache:
                use_count[key] += 1
                return cache[key]
            result = user_function(*args, **kwargs)
            cache[key] = result
            use_count[key] = 1
            if len(use_count) > maxsize:
                for k, _ in sorted(use_count.items(), key=lambda x: x[1])[:maxsize // 10]:
                    del cache[k]
                    del use_count[k]
            return result
        return wrapper
    return decorator
