def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Check if classes is an empty list
    if not classes:
        return classes
    # Create a set to store the base classes
    bases = set()
    # Iterate over the classes and add each base class to the set
    for cls in classes:
        for base in cls.__bases__:
            bases.add(base)
    # Return the ordered minimum equivalent of the base classes
    return sorted(bases, key=lambda x: x.__name__)

