def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for manifest in app.spec.manifest:
        if not manifest.observer_schema:
            manifest.observer_schema = generate_default_observer_schema_for_resource(manifest.resource)

def generate_default_observer_schema_for_resource(resource):
    if resource.kind == "Deployment":
        return DeploymentObserverSchema(spec=BaseDeploymentObserverSchema(label_selector=resource.spec.selector))
    elif resource.kind == "StatefulSet":
        # Stateful sets do not support label selectors, so we cannot create a default observer schema for them
        return None
    else:
        # Other resource kinds are not currently supported
        return None

