def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    # Determine the specification version to use for validation
    if extract_spec_version:
        field_type = inventory.get('type', None)
        if field_type is not None:
            try:
                spec_version = self.get_spec_version_for_type(field_type)
            except ValueError as e:
                raise SchemaFormatException(str(e), 'type') from e
    else:
        spec_version = self.spec_version

    # Validate the inventory based on the determined specification version
    if spec_version == 1:
        return self._validate_v1(inventory)
    else:
        raise SchemaFormatException("Unsupported specification version: " + repr(spec_version))

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    # Check that all needed digests are present
    for manifest_file in manifest_files:
        if manifest_file.digest not in self.digests_present:
            raise ValueError(f"Digest {manifest_file.digest} not found in metadata")

    # Check that all digests used are needed
    for digest in digests_used:
        if digest not in self.digests_needed:
            raise ValueError(f"Digest {digest} not needed in manifest")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("prior must be an InventoryValidator object.")

    if not self.parameters == prior.parameters:
        raise ValueError("The set of parameters must be the same for both inventories.")

    if not self.stoichiometry_matrix == prior.stoichiometry_matrix:
        raise ValueError("The stoichiometry matrices must be the same for both inventories.")

    if not self.propensities == prior.propensities:
        raise ValueError("The propensity matrices must be the same for both inventories.")

    if not self.species.keys() == prior.species.keys():
